package com.greenocean.backend.wellbeing.service;
import com.greenocean.backend.catalog.service.GrowthLibrary;
import com.greenocean.backend.common.exception.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
@Service @Transactional
public class ReviewedQuestions {
 private final JdbcTemplate db;private final GrowthLibrary library;
 public ReviewedQuestions(JdbcTemplate db,GrowthLibrary library){this.db=db;this.library=library;}
 public record Input(String body,String language,String rightsNote,List<String> sources,long etag){}
 public record Action(String action,long etag,String note,boolean sourcesChecked,boolean rightsChecked){}
 private String text(String value,int max,boolean required){return PrivateWellbeing.text(value,max,required);}
 private Map<String,Object> row(UUID id){var rows=db.queryForList("SELECT * FROM wellbeing_prompt_versions WHERE id=?",id);if(rows.isEmpty())throw new NotFoundException("Editorial question was not found");var r=rows.getFirst();r.put("sources",db.queryForObject("SELECT sources FROM wellbeing_prompt_versions WHERE id=?",(rs,n)->Arrays.asList((String[])rs.getArray(1).getArray()),id));return r;}
 private Map<String,Object> lock(UUID id,long etag){db.queryForList("SELECT id FROM wellbeing_prompt_versions WHERE id=? FOR UPDATE",id);var r=row(id);if(((Number)r.get("etag")).longValue()!=etag||!Objects.equals(r.get("revision"),db.queryForObject("SELECT max(revision) FROM wellbeing_prompt_versions WHERE prompt_key=?",Integer.class,r.get("prompt_key"))))throw new ConflictException("Question revision changed. Reload before acting.");return r;}
 private String[] sources(Input in){if(in.sources()==null)return new String[0];if(in.sources().size()>6)throw new IllegalArgumentException("At most six question references");return in.sources().stream().map(GrowthLibrary::external).toArray(String[]::new);}
 public Map<String,Object> save(UUID actor,UUID id,Input in,boolean fork){library.permission(actor,"DRAFT","GENERAL");String body=text(in.body(),1000,true),rights=text(in.rightsNote(),1000,true);if(!Set.of("en","fa").contains(in.language()))throw new IllegalArgumentException("Use an approved question language");String[] sources=sources(in);if(id==null){id=db.queryForObject("INSERT INTO wellbeing_prompt_versions(revision,language,body,author_id,rights_note,sources) VALUES (1,?,?,?,?,?) RETURNING id",UUID.class,in.language(),body,actor,rights,sources);}else{var r=lock(id,in.etag());if(!actor.equals(r.get("author_id")))throw new NotFoundException("Own editorial question was not found");if(fork)id=db.queryForObject("INSERT INTO wellbeing_prompt_versions(prompt_key,revision,language,body,author_id,rights_note,sources) VALUES (?,?,?,?,?,?,?) RETURNING id",UUID.class,r.get("prompt_key"),((Number)r.get("revision")).intValue()+1,in.language(),body,actor,rights,sources);else{if(!"DRAFT".equals(r.get("review_state")))throw new ConflictException("Create a new version before changing submitted or reviewed questions");db.update("UPDATE wellbeing_prompt_versions SET language=?,body=?,rights_note=?,sources=?,etag=etag+1 WHERE id=?",in.language(),body,rights,sources,id);}}return row(id);}
 public Map<String,Object> act(UUID actor,UUID id,Action in){library.actor(actor);var r=lock(id,in.etag());String note=text(in.note(),3000,true),action=in.action();if("SUBMIT".equals(action)){library.permission(actor,"SUBMIT","GENERAL");if(!actor.equals(r.get("author_id"))||!"DRAFT".equals(r.get("review_state")))throw new ConflictException("Only the current author draft may be submitted");db.update("UPDATE wellbeing_prompt_versions SET review_state='SUBMITTED',etag=etag+1 WHERE id=?",id);}else if(Set.of("APPROVE","NEEDS_REVISION","REJECT").contains(action)){library.staff(actor);library.permission(actor,"REVIEW","GENERAL");if(actor.equals(r.get("author_id")))throw new ForbiddenException("Independent question review is required");if(!"SUBMITTED".equals(r.get("review_state")))throw new ConflictException("Only the exact submitted question revision may be reviewed");if(action.equals("APPROVE")){library.permission(actor,"APPROVE","GENERAL");library.permission((UUID)r.get("author_id"),"SUBMIT","GENERAL");if(!in.sourcesChecked()||!in.rightsChecked())throw new IllegalArgumentException("Record actual source/originality and rights checks");}db.update("UPDATE wellbeing_prompt_versions SET review_state=?,reviewer_id=?,review_note=?,reviewed_at=CURRENT_TIMESTAMP,sources_checked=?,rights_checked=?,etag=etag+1 WHERE id=?",action.equals("APPROVE")?"APPROVED":action.equals("REJECT")?"REJECTED":"NEEDS_REVISION",actor,note,in.sourcesChecked(),in.rightsChecked(),id);}else if("PUBLISH".equals(action)){library.staff(actor);library.permission(actor,"PUBLISH","GENERAL");library.requirePublication();if(!"APPROVED".equals(r.get("review_state")))throw new ConflictException("The exact question revision needs independent approval");library.permission((UUID)r.get("author_id"),"SUBMIT","GENERAL");library.permission((UUID)r.get("reviewer_id"),"REVIEW","GENERAL");library.permission((UUID)r.get("reviewer_id"),"APPROVE","GENERAL");db.update("UPDATE wellbeing_prompt_versions SET status='RETIRED',review_state='RETIRED' WHERE prompt_key=? AND status='PUBLISHED' AND id<>?",r.get("prompt_key"),id);db.update("UPDATE wellbeing_prompt_versions SET status='PUBLISHED',review_state='PUBLISHED',etag=etag+1 WHERE id=?",id);}else if("RETIRE".equals(action)){library.staff(actor);library.permission(actor,"RETIRE","GENERAL");db.update("UPDATE wellbeing_prompt_versions SET status='RETIRED',review_state='RETIRED',etag=etag+1 WHERE id=?",id);}else throw new IllegalArgumentException("Unknown question action");return row(id);}
 public List<Map<String,Object>> workspace(UUID actor,int page){library.actor(actor);if(page<0||page>100000)throw new IllegalArgumentException("Invalid editorial page");var ids=db.queryForList("SELECT p.id FROM wellbeing_prompt_versions p WHERE p.revision=(SELECT max(latest.revision) FROM wellbeing_prompt_versions latest WHERE latest.prompt_key=p.prompt_key) AND(p.author_id=? OR(p.review_state='SUBMITTED' AND educational_permission_live(?,'REVIEW','GENERAL'))) ORDER BY p.created_at DESC,p.id LIMIT 30 OFFSET ?",UUID.class,actor,actor,(long)page*30);return ids.stream().map(this::row).toList();}
}
